head.script:
// 테스트 설명, 유효성 값 설정
//  ★ iframe > M > focus (standalone)
//   · iframe 은 브라우저 기본 focusable 엘리먼트이므로 focus() 호출 시 활성요소(document.activeElement)가 iframe 으로 이동한다(val1).
//   · iframe 플러그인은 userEvents = ["oniframeload","oniframeunload"] 만 제공 → onfocus 이벤트를 지원하지 않는다.
//     따라서 onfocus 핸들러가 아니라 focus() 호출 후 document.activeElement 로 포커스 이동을 검증한다.
//   · con_tabIndex / con_tagname 조건은 iframe DOM 엘리먼트에 반영하여 val2(포커스 관련 속성) 확인용으로 사용한다.
//     (iframe 은 tabIndex 유무와 무관하게 focus() 로 포커스 이동이 되므로 val1 이 주로 해당한다.)
scwin.tData = {
    "description" : "[iframe > M > focus]<br/>컴포넌트로 포커스를 이동시킵니다.",
    "validation" : [
        "포커스를 받을 수 있는 컴포넌트(InputBox, Button, TextArea 등)에 포커스가 이동되어야 합니다.",
        "포커스를 받을 수 없는 컴포넌트는 관련 속성(tabIndex, tagname 등)을 설정 시 포커스가 이동되어야 합니다."
    ]
}



scwin.onpageload = async function () {
    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - iframe 은 dynamicCreate 시 inline src 를 주면 미로딩 contentDocument.documentElement(null) 접근으로 TypeError 가 발생하므로
//    src 없이 생성한 뒤 setSrc(".xml 경로") 로 로드한다.
//  - con_tabIndex / con_tagname 조건을 iframe DOM 엘리먼트(render)에 setAttribute 로 반영한다.
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    let cTabIndex = con_tabIndex.getValue();
    let cTagName = con_tagname.getValue();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    await $c.gcm.createLabel('label="[전제] iframe 은 브라우저에서 기본적으로 포커스를 받을 수 있는(focusable) 엘리먼트입니다. iframe 은 onfocus 이벤트를 지원하지 않으므로(userEvents = oniframeload / oniframeunload) 이벤트가 아니라 focus() 호출 후 document.activeElement 로 포커스 이동을 확인합니다.\n[절차] (필요 시) tabIndex / tagname 조건 설정 후 [Target 재생성] → 아래 [focus] 버튼 클릭.\n[확인] focus() 호출 후 활성요소(activeElement)의 tagName 이 iframe 이고 id 가 iframe 컴포넌트(mf_target1)와 일치하면 포커스가 iframe 으로 이동한 것입니다. onfocus 이벤트는 발생하지 않습니다."', '', 'label1');

    // iframe 생성 (inline src 금지 → 생성 후 setSrc)
    let strTarget = '';
    strTarget += '<w2:iframe ' + strNameSpace + ' style="width:500px; height:250px;" id=""></w2:iframe>';
    scwin.target1 = await $p.dynamicCreate("target1", "iframe", strTarget, grp_comp);

    // 초기 로딩 시 iframe 이 비어 보이지 않도록 src 설정(.xml 경로 → 엔진이 래핑하여 로드)
    scwin.target1.setSrc("/sample/common_link/iframe_link_1.xml");

    // 조건(con_tabIndex / con_tagname) 을 iframe DOM 엘리먼트에 반영
    //  · el(render) : iframe 플러그인의 실제 <iframe> DOM 엘리먼트. focus() 는 이 엘리먼트의 focus() 를 호출한다.
    let el = scwin.target1.render;
    if (el !== null && typeof el !== 'undefined') {
        if (cTabIndex !== '' && cTabIndex !== null)
            el.setAttribute('tabindex', cTabIndex);
        // tagname 은 iframe 엘리먼트 태그를 바꿀 수 없으므로 참고 속성으로만 반영(표시 검증용)
        if (cTagName !== '' && cTagName !== null)
            el.setAttribute('data-tagname', cTagName);
    }
}



// [focus 버튼] : target1.focus() 호출 후 document.activeElement 로 포커스 이동 검증
//  - 호출 전 활성요소(방금 클릭한 focus 버튼)와 호출 후 활성요소를 비교하여 포커스가 iframe 으로 이동함을 확인한다.
//  - iframe 은 focusable 이므로 호출 후 activeElement 가 iframe(mf_target1)으로 이동한다.
scwin.btn_focus_onclick = function (e) {
    let b = wf_body_bottom.getObj("scwin");
    b.setReturnValue("===== focus() 호출 =====");

    // 호출 전 활성요소 (focus 버튼을 클릭했으므로 활성요소는 버튼 등 iframe 이 아닌 요소)
    let before = document.activeElement;
    b.setReturnValue("[focus() 호출 전] activeElement id : " + (before ? before.id : 'null') + " / tagName : " + (before ? before.tagName : 'null'));

    // iframe 의 공통 메소드 focus() 호출
    target1.focus();
    let after = document.activeElement;
    b.setReturnValue("[focus() 호출 후] activeElement id : " + (after ? after.id : 'null') + " / tagName : " + (after ? after.tagName : 'null'));

    let movedToIframe = !!(after && after.tagName && after.tagName.toLowerCase() === 'iframe');
    b.setReturnValue("iframe 으로 포커스 이동 여부 : " + (movedToIframe ? '이동됨 (활성요소 = iframe)' : '이동 안됨'));
    b.setReturnValue("iframe 컴포넌트 ID(getID) : " + target1.getID());
    b.setReturnValue("iframe tabindex 속성 : " + (target1.render ? target1.render.getAttribute('tabindex') : 'null'));
    b.setReturnValue("※ iframe 은 onfocus 이벤트 미지원(oniframeload / oniframeunload 만 제공) → onfocus 는 발생하지 않습니다.");
};
